//! Exact live completion profile and settings patch mapping. No identity/PIN/effects.
use serde::{Deserialize,Serialize};
#[derive(Deserialize)] #[serde(deny_unknown_fields,rename_all="camelCase")]
pub struct Input {pub account:String,pub time:i64,pub goals:Vec<String>,pub start:String,pub end:String,pub choice:String,pub cycle_option:String,pub option_blank:bool,pub cycle:i32,pub duration:i32,pub fertile:bool,pub symptoms:Vec<String>,pub energy:String,pub sleep:String,pub deep:bool}
#[derive(Deserialize,Serialize)] #[serde(deny_unknown_fields,rename_all="camelCase")]
pub struct Profile {pub id:i32,pub is_completed:bool,pub completed_at_timestamp:i64,pub is_age_verified:bool,pub is_terms_agreed:bool,pub account_mode:String,pub selected_goals_csv:String,pub last_period_date_string:String,pub last_period_end_date_string:String,pub approximate_period_choice:String,pub cycle_length_option:String,pub cycle_length_days:i32,pub period_duration_days:i32,pub remind_fertile_window:bool,pub typical_symptoms_csv:String,pub typical_energy:String,pub typical_sleep_quality:String,pub has_completed_deep_baseline:bool}
pub fn profile(i:Input)->Profile {Profile{id:1,is_completed:true,completed_at_timestamp:i.time,is_age_verified:true,is_terms_agreed:true,account_mode:i.account,selected_goals_csv:i.goals.join(","),last_period_date_string:if i.choice=="UNKNOWN"{String::new()}else{i.start},last_period_end_date_string:i.end,approximate_period_choice:i.choice,cycle_length_option:if i.option_blank{"UNKNOWN".into()}else{i.cycle_option},cycle_length_days:i.cycle,period_duration_days:i.duration,remind_fertile_window:i.fertile,typical_symptoms_csv:i.symptoms.join(","),typical_energy:i.energy,typical_sleep_quality:i.sleep,has_completed_deep_baseline:i.deep}}
pub fn patch(p:Profile,lock:bool)->serde_json::Value {serde_json::json!({"isOnboardingCompleted":true,"selectedGoalsCsv":p.selected_goals_csv,"lastPeriodStartDate":p.last_period_date_string,"averageCycleLength":p.cycle_length_days,"periodDuration":p.period_duration_days,"remindFertile":p.remind_fertile_window,"isAppLockEnabled":lock})}
